NS_IMETHOD OnMessageUpdated(const nsACString& ewsId,
                            IHeaderBlock* headerBlock, uint32_t messageSize,
                            bool isRead, bool isFlagged,
                            const nsACString& preview) override {
  RefPtr<nsIMsgDBHdr> msgHdr;
  nsresult rv = mDB->GetMsgHdrForEwsItemID(ewsId, getter_AddRefs(msgHdr));
  NS_ENSURE_SUCCESS(rv, rv);
  if (!msgHdr) {
    // We might be in a weird situation where the server told us of an update
    // before a creation, or it might be that the server does not distinguish
    // the two cases. Either way, let the consumer know in case it wants to
    // try creating the message instead.
    return NS_MSG_MESSAGE_NOT_FOUND;
  }

  // If there's an offline copy of the raw message, delete it.
  // The message content might have changed (e.g. if a draft was updated),
  // and there's no way for us to know for sure without re-downloading it.
  uint32_t flags;
  rv = msgHdr->GetFlags(&flags);
  NS_ENSURE_SUCCESS(rv, rv);

  if ((flags & nsMsgMessageFlags::Offline)) {
    // Delete the message content from the local store.
    nsCOMPtr<nsIMsgPluggableStore> store;
    rv = mFolder->GetMsgStore(getter_AddRefs(store));
    NS_ENSURE_SUCCESS(rv, rv);

    rv = store->DeleteMessages({msgHdr});
    NS_ENSURE_SUCCESS(rv, rv);

    // Update the flags on the database entry to reflect its content is *not*
    // stored offline anymore.
    flags &= ~nsMsgMessageFlags::Offline;
  }

  // Apply updates to the nsIMsgHdr object.
  RawHdr updated = ParseHeaderBlock(headerBlock);

  if (isRead) {
    flags |= nsMsgMessageFlags::Read;
  } else {
    flags &= ~nsMsgMessageFlags::Read;
  }
  if (isFlagged) {
    flags |= nsMsgMessageFlags::Marked;
  } else {
    flags &= ~nsMsgMessageFlags::Marked;
  }
  // Use the parsed subject for HasRe, but ignore X-Mozilla-Status for all
  // other flags.
  flags = (flags & ~nsMsgMessageFlags::HasRe) |
          (updated.flags & nsMsgMessageFlags::HasRe);
  updated.flags = flags;

  // We need the old flags to notify listeners.
  uint32_t oldFlags;
  MOZ_TRY(msgHdr->GetFlags(&oldFlags));

  // Update the database entry, then notify any listener to let them know
  // about the changes.
  MOZ_TRY(ApplyRawHdrToDbHdr(updated, msgHdr));
  // ApplyRawHdrToDbHdr skips empty subjects. A subject containing only a
  // reply prefix has an empty stored value and must replace the old one.
  if (updated.subject.IsEmpty() && (flags & nsMsgMessageFlags::HasRe)) {
    MOZ_TRY(msgHdr->SetSubject(""_ns));
  }

  // Setting `instigator` (the 4th argument to `NotifyHdrChangeAll`) to
  // nullptr should be fine here, the only listener that actually cares about
  // it is the `nsMsgDBView` to check whether it instigated the change itself
  // (which it hasn't in this case).
  MOZ_TRY(mDB->NotifyHdrChangeAll(msgHdr, oldFlags, flags, nullptr));

  if (messageSize) {
    MOZ_TRY(msgHdr->SetMessageSize(messageSize));
  }
  if (!preview.IsEmpty()) {
    MOZ_TRY(msgHdr->SetStringProperty("preview", preview));
  }

  MOZ_TRY(mDB->Commit(nsMsgDBCommitType::kLargeCommit));
  return NS_OK;
